# =============================================================================
# Challenge 1: Timestamp Calibration Logic (R6)
# =============================================================================
class TestChallengerTimestampCalibration:
    """Adversarial stress-testing of TimestampCalibrationService."""

    def test_adv_timestamp_zero_and_near_zero_clamping(self):
        svc = TimestampCalibrationService()
        segments = [
            {"start": 0.0, "end": 4.5, "text": "Bienvenido al curso."},
            {"start": 4.5, "end": 9.0, "text": "Hoy veremos algoritmos."},
        ]
        # Any start time < 5.0 must clamp strictly to 0.0s
        assert svc.calibrate(segments, 0.0) == 0.0
        assert svc.calibrate(segments, 0.5) == 0.0
        assert svc.calibrate(segments, 4.99) == 0.0
        assert svc.calibrate(segments, -10.0) == 0.0

    def test_adv_timestamp_empty_segments_fallback(self):
        svc = TimestampCalibrationService()
        # Fallback when no segments are available
        assert svc.calibrate([], 0.0) == 0.0
        assert svc.calibrate([], 3.0) == 0.0
        # For 10.0s with no segments, lead-in is min(10.0, 7.5) = 7.5 -> 2.5s
        res = svc.calibrate([], 10.0)
        assert res == 2.5
        assert 5.0 <= (10.0 - res) <= 10.0

    def test_adv_timestamp_huge_gap_between_segments(self):
        svc = TimestampCalibrationService()
        # Segment 0 at 0-5s, gap of 95s, Segment 1 at 100-110s
        segments = [
            {"start": 0.0, "end": 5.0, "text": "Intro"},
            {"start": 100.0, "end": 110.0, "text": "Explicación principal tras largo silencio."},
        ]
        # Topic starts at 105.0s
        calibrated = svc.calibrate(segments, 105.0)
        # Lead in must be in valid range [5.0, 10.0] or snapped to segment start if within range
        lead_in = 105.0 - calibrated
        assert 5.0 <= lead_in <= 10.0
        assert calibrated >= 0.0

    def test_adv_timestamp_dense_rapid_fire_segments(self):
        svc = TimestampCalibrationService()
        # 30 segments of 0.5s each spanning 0.0s to 15.0s
        segments = [
            {"start": round(i * 0.5, 1), "end": round((i + 1) * 0.5, 1), "text": f"palabra {i}"}
            for i in range(30)
        ]
        # Topic starts at 12.0s
        calibrated = svc.calibrate(segments, 12.0)
        lead_in = 12.0 - calibrated
        # Must snap to one of the segment starts within [5.0, 10.0] lead-in
        assert 5.0 <= lead_in <= 10.0
        assert any(abs(calibrated - seg["start"]) < 0.01 for seg in segments)

    def test_adv_timestamp_single_long_monologue_segment(self):
        svc = TimestampCalibrationService()
        # One long segment from 0.0s to 300.0s
        segments = [{"start": 0.0, "end": 300.0, "text": "Monólogo ininterrumpido sin pausas."}]
        calibrated = svc.calibrate(segments, 45.0)
        lead_in = 45.0 - calibrated
        assert 5.0 <= lead_in <= 10.0
        assert calibrated >= 0.0

    def test_adv_timestamp_quiz_batch_calibration(self):
        svc = TimestampCalibrationService()
        segments = [
            {"start": 0.0, "end": 6.0, "text": "Introducción."},
            {"start": 6.0, "end": 14.0, "text": "Concepto de variables y memoria."},
            {"start": 14.0, "end": 22.0, "text": "Estructuras condicionales if else."},
            {"start": 22.0, "end": 30.0, "text": "Bucles while y for iterativos."},
        ]
        quiz = {
            "multiple_choice": [
                {"question": "¿Qué es una variable?", "evidence_timestamp": "00:00:15"},
                {"question": "¿Cómo funciona un bucle?", "evidence_timestamp": "00:00:25"},
            ],
            "open_questions": [
                {"question": "Diferencia entre for y while.", "evidence_timestamp": "00:00:28"},
            ],
        }
        calibrated_quiz = svc.calibrate_quiz(quiz, segments)
        mc1 = calibrated_quiz["multiple_choice"][0]
        mc2 = calibrated_quiz["multiple_choice"][1]
        oq1 = calibrated_quiz["open_questions"][0]

        # Verify raw timestamps are preserved and evidence_timestamps are updated
        assert mc1["raw_timestamp"] == "00:00:15"
        assert mc1["evidence_timestamp"] != "00:00:15"
        secs_mc1 = svc.from_timestamp_string(mc1["evidence_timestamp"])
        assert 5.0 <= (15.0 - secs_mc1) <= 10.0


