# Challenge 2: Quiz Answer Masking (R4) & Role Permissions RBAC
# =============================================================================
class TestChallengerQuizMaskingAndRBAC:
    """Adversarial stress-testing of quiz answer stripping and role enforcement."""

    def test_adv_quiz_student_payload_inspection_no_answers_leaked(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, teacher_token, teacher_hdr = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        student_id, student_token, student_hdr = register_and_login(client, f"s_{uuid.uuid4().hex[:6]}@school.com", "Alumno")

        video = create_test_video(db_session, owner_id=teacher_id)
        quiz = create_test_quiz(db_session, video_id=video.id, owner_id=teacher_id)
        group_id, group_code, topic_id = create_test_group_and_topic(client, teacher_token, video.id, quiz.id)

        # Student joins group
        client.post("/api/v1/groups/join", json={"code": group_code}, headers=student_hdr)

        # 1. Student calls GET /api/v1/materials/{id} directly
        res = client.get(f"/api/v1/materials/{quiz.id}", headers=student_hdr)
        assert res.status_code == 200
        content = res.json()["content"]
        for mc in content.get("multiple_choice", []):
            assert "correct_option" not in mc, "LEAK: correct_option exposed to student via direct material endpoint!"
            assert "explanation" not in mc, "LEAK: explanation exposed to student via direct material endpoint!"
        for oq in content.get("open_questions", []):
            assert "expected_points" not in oq, "LEAK: expected_points exposed to student via direct material endpoint!"

        # 2. Student calls GET /api/v1/groups/{group_id}/topics/{topic_id}/materials
        topic_mats_res = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/materials", headers=student_hdr)
        assert topic_mats_res.status_code == 200
        shared_quiz = topic_mats_res.json()["shared_quiz"]
        assert shared_quiz is not None
        for mc in shared_quiz["content"].get("multiple_choice", []):
            assert "correct_option" not in mc, "LEAK: correct_option exposed to student via topic materials endpoint!"
            assert "explanation" not in mc, "LEAK: explanation exposed to student via topic materials endpoint!"

    def test_adv_quiz_student_export_with_answers_blocked_across_all_formats(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, teacher_token, _ = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        student_id, student_token, student_hdr = register_and_login(client, f"s_{uuid.uuid4().hex[:6]}@school.com", "Alumno")

        video = create_test_video(db_session, owner_id=teacher_id)
        quiz = create_test_quiz(db_session, video_id=video.id, owner_id=teacher_id)

        # Student attempts to export with include_answers=true on json, markdown, docx, pdf
        for fmt in ["json", "markdown", "docx", "pdf"]:
            res = client.get(
                f"/api/v1/materials/{quiz.id}/export?format={fmt}&include_answers=true",
                headers=student_hdr,
            )
            assert res.status_code == 403, f"Security exploit: student was able to request {fmt} export with include_answers=true!"

    def test_adv_quiz_anonymous_export_denied_answers(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, _, _ = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        video = create_test_video(db_session, owner_id=teacher_id)
        quiz = create_test_quiz(db_session, video_id=video.id, owner_id=teacher_id)

        # Anonymous request with include_answers=true must be rejected
        res = client.get(f"/api/v1/materials/{quiz.id}/export?format=json&include_answers=true")
        assert res.status_code == 403

    def test_adv_rbac_student_blocked_from_admin_endpoints(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, teacher_token, _ = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        student_id, student_token, student_hdr = register_and_login(client, f"s_{uuid.uuid4().hex[:6]}@school.com", "Alumno")

        video = create_test_video(db_session, owner_id=teacher_id)
        quiz = create_test_quiz(db_session, video_id=video.id, owner_id=teacher_id)
        group_id, group_code, topic_id = create_test_group_and_topic(client, teacher_token, video.id, quiz.id)

        client.post("/api/v1/groups/join", json={"code": group_code}, headers=student_hdr)

        # All admin attempt & summary endpoints must reject student with 403
        assert client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts", headers=student_hdr).status_code == 403
        assert client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/members/{student_id}/attempts", headers=student_hdr).status_code == 403
        assert client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/summary", headers=student_hdr).status_code == 403
        assert client.patch(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts/1",
            json={"final_score": 100.0, "review_notes": "hack"},
            headers=student_hdr,
        ).status_code == 403


