# Challenge 3: Activity Grading & Attempt Querying (R1 & R2)
# =============================================================================
class TestChallengerGradingAndAttempts:
    """Adversarial stress-testing of multi-student activity view, isolation, and boundary scores."""

    def test_adv_multi_student_status_summary_and_attempt_isolation(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, teacher_token, teacher_hdr = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        s1_id, s1_tok, s1_hdr = register_and_login(client, f"s1_{uuid.uuid4().hex[:6]}@school.com", "Alumno Uno")
        s2_id, s2_tok, s2_hdr = register_and_login(client, f"s2_{uuid.uuid4().hex[:6]}@school.com", "Alumno Dos")
        s3_id, s3_tok, s3_hdr = register_and_login(client, f"s3_{uuid.uuid4().hex[:6]}@school.com", "Alumno Tres")

        video = create_test_video(db_session, owner_id=teacher_id)
        quiz = create_test_quiz(db_session, video_id=video.id, owner_id=teacher_id)
        group_id, group_code, topic_id = create_test_group_and_topic(client, teacher_token, video.id, quiz.id)

        # Enroll all 3 students
        for hdr in [s1_hdr, s2_hdr, s3_hdr]:
            client.post("/api/v1/groups/join", json={"code": group_code}, headers=hdr)

        # Student 1 submits 2 attempts
        sub1 = client.post(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts",
            json={
                "multiple_choice_answers": [
                    {"question_index": 0, "selected_option": 1},
                    {"question_index": 1, "selected_option": 1},
                ],
            },
            headers=s1_hdr,
        )
        assert sub1.status_code == 201
        att1_id = sub1.json()["id"]

        sub2 = client.post(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts",
            json={
                "multiple_choice_answers": [
                    {"question_index": 0, "selected_option": 1},
                    {"question_index": 1, "selected_option": 0},
                ],
            },
            headers=s1_hdr,
        )
        assert sub2.status_code == 201

        # Student 2 submits 1 attempt
        sub3 = client.post(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts",
            json={
                "multiple_choice_answers": [
                    {"question_index": 0, "selected_option": 0},
                    {"question_index": 1, "selected_option": 0},
                ],
            },
            headers=s2_hdr,
        )
        assert sub3.status_code == 201
        att2_id = sub3.json()["id"]

        # Student 3 submits 0 attempts

        # Verify Teacher's topic summary
        summary_res = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/summary", headers=teacher_hdr)
        assert summary_res.status_code == 200
        summary_data = summary_res.json()
        members = summary_data["members_summary"]
        mem_map = {m["user_id"]: m for m in members}
        assert {s1_id, s2_id, s3_id}.issubset(mem_map.keys())
        assert mem_map[s1_id]["total_attempts"] == 2
        assert mem_map[s2_id]["total_attempts"] == 1
        assert mem_map[s3_id]["total_attempts"] == 0
        assert mem_map[s3_id]["status"] == "not_submitted"
        assert mem_map[s3_id]["final_score"] is None

        # Verify Student 1 views only their 2 attempts
        s1_atts = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/my-attempts", headers=s1_hdr).json()
        assert len(s1_atts) == 2
        assert {a["attempt_number"] for a in s1_atts} == {1, 2}

        # Verify Student 2 views only their 1 attempt
        s2_atts = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/my-attempts", headers=s2_hdr).json()
        assert len(s2_atts) == 1
        assert s2_atts[0]["attempt_number"] == 1

        # Verify Student 3 views 0 attempts
        s3_atts = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/my-attempts", headers=s3_hdr).json()
        assert len(s3_atts) == 0

        # Teacher queries specific student attempts via dedicated endpoint
        t_s1_atts = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/members/{s1_id}/attempts", headers=teacher_hdr).json()
        assert len(t_s1_atts) == 2
        assert all(a["user_id"] == s1_id for a in t_s1_atts)

        t_s3_atts = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/members/{s3_id}/attempts", headers=teacher_hdr).json()
        assert len(t_s3_atts) == 0

        # Boundary score modifications by Teacher
        # Max boundary: 100.0
        p_max = client.patch(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts/{att1_id}",
            json={"final_score": 100.0, "review_notes": "Sobresaliente"},
            headers=teacher_hdr,
        )
        assert p_max.status_code == 200
        assert p_max.json()["final_score"] == 100.0

        # Min boundary: 0.0
        p_min = client.patch(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts/{att2_id}",
            json={"final_score": 0.0, "review_notes": "Sin aciertos"},
            headers=teacher_hdr,
        )
        assert p_min.status_code == 200
        assert p_min.json()["final_score"] == 0.0

        # Invalid boundary scores: negative (<0) and excess (>100)
        p_neg = client.patch(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts/{att1_id}",
            json={"final_score": -1.0, "review_notes": "Inválido"},
            headers=teacher_hdr,
        )
        assert p_neg.status_code in [400, 422]

        p_exc = client.patch(
            f"/api/v1/groups/{group_id}/topics/{topic_id}/attempts/{att1_id}",
            json={"final_score": 105.0, "review_notes": "Inválido"},
            headers=teacher_hdr,
        )
        assert p_exc.status_code in [400, 422]


