# Challenge 4: Video Search & Sorting (R3)
# =============================================================================
class TestChallengerVideoSearchAndSort:
    """Adversarial stress-testing of video search and chronological sorting."""

    def test_adv_video_search_special_characters_and_sql_injection(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, _, teacher_hdr = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")

        # Create videos with adversarial titles
        now = datetime.now(timezone.utc)
        v1 = create_test_video(db_session, owner_id=teacher_id, title="Normal Video Alpha", created_at=now - timedelta(hours=3))
        v2 = create_test_video(db_session, owner_id=teacher_id, title="100% Cotton & Special_Chars", created_at=now - timedelta(hours=2))
        v3 = create_test_video(db_session, owner_id=teacher_id, title="Injection'; DROP TABLE videos; --", created_at=now - timedelta(hours=1))
        v4 = create_test_video(db_session, owner_id=teacher_id, title="Unicode 🚀 Exploración de Datos", created_at=now)

        # 1. Search with SQL injection payload — must safely match title without SQL syntax error
        res_inj = client.get("/api/v1/videos?search=DROP TABLE", headers=teacher_hdr)
        assert res_inj.status_code == 200
        items = res_inj.json()["items"]
        assert len(items) == 1
        assert items[0]["id"] == v3.id

        # 2. Search with % wildcard character
        res_pct = client.get("/api/v1/videos?search=100%", headers=teacher_hdr)
        assert res_pct.status_code == 200
        assert any(item["id"] == v2.id for item in res_pct.json()["items"])

        # 3. Search with unicode emoji
        res_uni = client.get("/api/v1/videos?search=🚀", headers=teacher_hdr)
        assert res_uni.status_code == 200
        assert any(item["id"] == v4.id for item in res_uni.json()["items"])

        # 4. Search with whitespace only — must return all videos
        res_spc = client.get("/api/v1/videos?search=   ", headers=teacher_hdr)
        assert res_spc.status_code == 200
        assert len(res_spc.json()["items"]) >= 4

        # 5. Chronological order toggle: asc vs desc
        res_asc = client.get("/api/v1/videos?order=asc", headers=teacher_hdr).json()["items"]
        res_desc = client.get("/api/v1/videos?order=desc", headers=teacher_hdr).json()["items"]

        # Ascending: oldest created_at first
        my_asc = [v for v in res_asc if v["id"] in {v1.id, v2.id, v3.id, v4.id}]
        assert my_asc[0]["id"] == v1.id
        assert my_asc[-1]["id"] == v4.id

        # Descending: newest created_at first
        my_desc = [v for v in res_desc if v["id"] in {v1.id, v2.id, v3.id, v4.id}]
        assert my_desc[0]["id"] == v4.id
        assert my_desc[-1]["id"] == v1.id


