# Challenge 5: Summary Isolation (R5)
# =============================================================================
class TestChallengerSummaryIsolation:
    """Adversarial stress-testing of official vs personal summary separation and permissions."""

    def test_adv_summary_isolation_official_immutable_by_student(
        self, client: TestClient, db_session: Session
    ):
        teacher_id, teacher_token, teacher_hdr = register_and_login(client, f"t_{uuid.uuid4().hex[:6]}@school.com", "Profesor")
        s1_id, s1_tok, s1_hdr = register_and_login(client, f"s1_{uuid.uuid4().hex[:6]}@school.com", "Alumno Uno")
        s2_id, s2_tok, s2_hdr = register_and_login(client, f"s2_{uuid.uuid4().hex[:6]}@school.com", "Alumno Dos")

        video = create_test_video(db_session, owner_id=teacher_id)
        official_summary = create_test_summary(db_session, video_id=video.id, owner_id=teacher_id, synopsis="Sinopsis oficial del docente.")
        group_id, group_code, topic_id = create_test_group_and_topic(client, teacher_token, video.id)

        # Students enroll
        client.post("/api/v1/groups/join", json={"code": group_code}, headers=s1_hdr)
        client.post("/api/v1/groups/join", json={"code": group_code}, headers=s2_hdr)

        # 1. Student 1 attempts to modify official teacher summary directly
        put_payload = {
            "content": {
                "synopsis": "Resumen hackeado por alumno",
                "glossary": [],
                "didactic_blocks": [
                    {"title": "Hacked", "explanation": "Contenido modificado", "timestamps": ["00:00:05"]}
                ],
                "evidence_sufficient": True,
            }
        }
        res_hack = client.put(f"/api/v1/materials/{official_summary.id}", json=put_payload, headers=s1_hdr)
        assert res_hack.status_code == 403, "CRITICAL: Student was able to edit teacher's official summary!"

        # 2. Student 1 creates personal summary
        personal_summary_s1 = create_test_summary(
            db_session, video_id=video.id, owner_id=s1_id, synopsis="Mi resumen personal como estudiante 1."
        )

        # 3. Student 1 edits their personal summary -> allowed (200)
        s1_edit_payload = {
            "content": {
                "synopsis": "Mi resumen personal actualizado con notas propias.",
                "glossary": [{"term": "Término A", "definition": "Def A", "timestamp": "00:00:10"}],
                "didactic_blocks": [
                    {"title": "Bloque Propio", "explanation": "Mis notas", "timestamps": ["00:00:10"]}
                ],
                "evidence_sufficient": True,
            }
        }
        res_s1_edit = client.put(f"/api/v1/materials/{personal_summary_s1.id}", json=s1_edit_payload, headers=s1_hdr)
        assert res_s1_edit.status_code == 200
        assert res_s1_edit.json()["content"]["synopsis"] == "Mi resumen personal actualizado con notas propias."

        # 4. Student 2 tries to edit Student 1's personal summary -> blocked (403)
        res_s2_hack = client.put(f"/api/v1/materials/{personal_summary_s1.id}", json=put_payload, headers=s2_hdr)
        assert res_s2_hack.status_code == 403, "CRITICAL: Student 2 was able to edit Student 1's personal summary!"

        # 5. Teacher checks topic materials: shared_summary is intact
        t_mats = client.get(f"/api/v1/groups/{group_id}/topics/{topic_id}/materials", headers=teacher_hdr).json()
        assert t_mats["shared_summary"]["id"] == official_summary.id
        assert t_mats["shared_summary"]["content"]["synopsis"] == "Sinopsis oficial del docente."
